PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS SchemaMigration (version INTEGER PRIMARY KEY, appliedAt TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS UserSettings (id TEXT PRIMARY KEY CHECK(id = 'default'), data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS Metadata (id INTEGER PRIMARY KEY CHECK(id=1), revision INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS StudyTask (id TEXT PRIMARY KEY, date TEXT NOT NULL, status TEXT NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE INDEX IF NOT EXISTS task_date_status ON StudyTask(date,status);
CREATE TABLE IF NOT EXISTS StudyPlan (id TEXT PRIMARY KEY, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS KnowledgeTopic (id TEXT PRIMARY KEY, taskId TEXT NOT NULL REFERENCES StudyTask(id), data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS StudySession (id TEXT PRIMARY KEY, taskId TEXT NOT NULL REFERENCES StudyTask(id), data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS ReviewEvent (id TEXT PRIMARY KEY, taskId TEXT NOT NULL REFERENCES StudyTask(id), stage INTEGER NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)), UNIQUE(taskId,stage));
CREATE INDEX IF NOT EXISTS review_task ON ReviewEvent(taskId);
CREATE TABLE IF NOT EXISTS WrongQuestion (id TEXT PRIMARY KEY, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS ExamPractice (id TEXT PRIMARY KEY, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS InterviewPractice (id TEXT PRIMARY KEY, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS TeachingSchedule (id TEXT PRIMARY KEY, date TEXT NOT NULL UNIQUE, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS ChatConversation (id TEXT PRIMARY KEY, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS ChatMessage (id TEXT PRIMARY KEY, conversationId TEXT NOT NULL REFERENCES ChatConversation(id), data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS AIActionLog (id TEXT PRIMARY KEY, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS ImportBatch (id TEXT PRIMARY KEY, hash TEXT NOT NULL UNIQUE, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS RescheduleProposal (id TEXT PRIMARY KEY, data TEXT NOT NULL CHECK(json_valid(data)));
